// Changes: Native radios in a <fieldset> with a visually hidden <legend> (arrow keys, form semantics for free);
//          the checked/focused state is styled on the pill via :has() (styles.css .seg-option).
export function Segmented<V extends string | number>({
  label,
  value,
  options,
  onChange,
  size = 'md',
}: {
  label: string
  value: V
  options: { value: V; label: ReactNode }[]
  onChange: (value: V) => void
  size?: 'sm' | 'md'
}) {
  const name = useId()
  return (
    <fieldset className="m-0 inline-flex min-w-0 rounded-full border border-white/10 bg-white/5 p-0.5">
      <legend className="sr-only">{label}</legend>
      {options.map((o) => (
        <label
          key={String(o.value)}
          className={cx(
            'seg-option relative cursor-pointer rounded-full tabular-nums transition-colors',
            size === 'sm' ? 'px-2.5 py-1 text-xs' : 'px-4 py-1.5 text-sm',
          )}
        >
          <input
            type="radio"
            name={name}
            value={String(o.value)}
            checked={value === o.value}
            onChange={() => onChange(o.value)}
            className="sr-only"
          />
          {o.label}
        </label>
      ))}
    </fieldset>
  )
}

